INTRX1_HANDLER:		; 1F736
	PUSH XIZ
	PUSH XIY
	PUSH XIX
	PUSH XHL
	PUSH XDE
	PUSH XBC
	PUSH XWA
	LD C, (SC1BUF)
	LD A, (SC1CR)
	AND A, 01ch    ; 0001 1100
	JR Z, LABEL_1F74F
	
	; serial comms error happened:
	LD (1036h), (SC1CR)
	JR T, exit_INTRX1_HANDLER

LABEL_1F74F:
	BIT 2, (SERIAL_1_VAR_1034)
	JR Z, LABEL_1F75D
	LD XWA, 00000e00h
	CALR SAVE_BYTE_TO_RING_BUFFER

exit_INTRX1_HANDLER:  ; 1F75D
	POP XWA
	POP XBC
	POP XDE
	POP XHL
	POP XIX
	POP XIY
	POP XIZ
	RETI


INTTX1_HANDLER:		; 1F765
	PUSH XIZ
	PUSH XIY
	PUSH XIX
	PUSH XHL
	PUSH XDE
	PUSH XBC
	PUSH XWA
	BIT 0, (SERIAL_1_VAR_1034)
	JR Z, LABEL_1F77B
	RES 0, (SERIAL_1_VAR_1034)
	LD (SC1BUF), 0feh
	JR T, LABEL_1F78C

LABEL_1F77B:
	LD XWA, 00001016h
	CALR READ_BYTE_FROM_RING_BUFFER
	CP HL, 0ffffh
	JR Z, LABEL_1F78C
	LD (SC1BUF), L

LABEL_1F78C:
	BIT 0, (SERIAL_1_VAR_1034)
	JR NZ, LABEL_1F7A3
	LD XWA, 00001016h
	CALR RING_BUFFER_HAS_OVERRUN
	CP HL, 0ffffh
	JR NZ, LABEL_1F7A3
	LD (INTES1), 0fdh

LABEL_1F7A3:
	POP XWA
	POP XBC
	POP XDE
	POP XHL
	POP XIX
	POP XIY
	POP XIZ
	RETI


; returns:
; HL = 0ffffh (True)
; HL = 0000h (False)
;
RING_BUFFER_HAS_OVERRUN:  ; 1F7AB
	LD HL, 0
	LD XBC, (XWA + 00ch)  ; current_read_pointer
	CP XBC, (XWA + 008h)  ; current_write_pointer
	RET NZ
	LD HL, 0ffffh
	RET


READ_BYTE_FROM_RING_BUFFER:		; 1F7B9
	LD HL, 0ffffh
	LDA XDE, XWA + 008h  ; current_write_pointer
	LD XBC, (XDE)
	LD XIX, XBC
	CP (XWA + 00ch), XBC  ; current_read_pointer
	RET Z
	LD L, (XBC)
	CP XBC, (XWA + 004h)  ; buffer_end
	JR NZ, LABEL_1F7D3
	LD XIX, (XWA)  ; buffer_start
	JR T, LABEL_1F7D5

LABEL_1F7D3:
	INC 1, XIX

LABEL_1F7D5:
	LD (XDE), XIX
	INCW 1, (XWA + 014h)
	EXTZ HL
	RET


SAVE_BYTE_TO_RING_BUFFER:	; 1F7DD
	LDA XIX, XWA + 014h
	LD HL, (XIX)
	LDA XDE, XWA + 00ch
	LD XIY, (XDE)
	CP HL, 0
	RET Z
	LD (XIY), C
	CP XIY, (XWA + 004h)
	JR NZ, LABEL_1F7F6
	LD XIY, (XWA)
	JR T, LABEL_1F7F8

LABEL_1F7F6:
	INC 1, XIY

LABEL_1F7F8:
	LD (XDE), XIY
	LD HL, (XIX)
	DEC 1, HL
	LD (XIX), HL
	RET


LABEL_1F801:
	PUSH SR
	EI 6
	LD (INTES1), 0ddh
	POP SR
	RET
LABEL_1F809:
	db 002h, 006h, 006h, 008h, 0EBh, 0FDh, 003h, 00Eh

LABEL_1F811:
	CP A, 0f5h
	JR Z, LABEL_1F82C
	CP A, 0f4h
	RET NZ
	LD (SERIAL_1_VAR_1038), 003h
	SET 2, (SERIAL_1_VAR_1034)
	EI 6
	LD (SC1MOD), 02bh
	EI 0
	RET

LABEL_1F82C:
	LD (SERIAL_1_VAR_1038), 002h
	SET 2, (SERIAL_1_VAR_1034)
	RET

LABEL_1F836:
	LD XWA, (102Ch)
	LD XBC, (1040h)
	LD XDE, XBC
	SUB XDE, XWA
	CP XDE, 00000087h
	RET C
	LD (102Ch), XBC
	SET 0, (SERIAL_1_VAR_1034)
	CALR LABEL_1F801
	RET

LABEL_1F856:
	PUSH IZ
	LD IZ, 0

LABEL_1F859:
	LD XWA, 00000e00h
	CALR READ_BYTE_FROM_RING_BUFFER
	CP HL, 0ffffh
	JR Z, LABEL_1F87B
	LD WA, IZ
	INC 1, IZ
	LDA XBC, 0600h
	EXTZ XWA
	ADD XWA, XBC
	LD (XWA), L
	CP IZ, 0400h
	JR C, LABEL_1F859

LABEL_1F87B:
	CP IZ, 0
	JR Z, LABEL_1F88E
	EI 0
	LD WA, 4
	LD BC, IZ
	LD XDE, 00000600h
	CALL LABEL_20C6B

LABEL_1F88E:
	POP IZ
	RET

LABEL_1F890:
	LD A, (XSP + 004h)
	DEC 1, (XSP + 004h)
	CP A, 0
	JR Z, LABEL_1F8D2

LABEL_1F89A:
	BIT 2, (SERIAL_1_VAR_1034)
	JR NZ, LABEL_1F8B2
	LD XWA, (XSP + 006h)
	LD C, (XWA+)
	LD (XSP + 006h), XWA
	EXTZ BC
	LD WA, BC
	CALR LABEL_1F811
	JR T, LABEL_1F8C8

LABEL_1F8B2:
	LD XWA, (XSP + 006h)
	LD C, (XWA+)
	LD (XSP + 006h), XWA
	EXTZ BC
	LD XWA, 00001016h
	CALR SAVE_BYTE_TO_RING_BUFFER
	CALR LABEL_1F801

LABEL_1F8C8:
	LD A, (XSP + 004h)
	DEC 1, (XSP + 004h)
	CP A, 0
	JR NZ, LABEL_1F89A

LABEL_1F8D2:
	LD HL, 0
	RET

LABEL_1F8D5:
	PUSH SR
	EI 6
	CALR LABEL_1F856
	POP SR
	JRL T, LABEL_1F836

INIT_RING_BUFFERS:
	LD (SERIAL_1_VAR_1034), 000h
	SET 0, (SERIAL_1_VAR_1034)
	LD (SERIAL_1_VAR_1038), 000h
	LD XIY, LABEL_00F434
	LD XIX, 00000e00h
	LD BC, 000bh
	LDIRW
	LD XIY, LABEL_00f44a
	LD XIX, 00001016h
	LD BC, 000bh
	LDIRW
	EI 6 ; <-------  1f90b
	LD (SC1MOD), 029h
	LD (SC1CR), 000h
	LD (BR1CR), 00ah
	LD (INTES1), 05dh
	LD (SC1BUF), 0feh
	EI 0
	RET

LABEL_1F91F:
	db 005h, 00Eh, 068h, 001h, 00Eh


